// DEMO_MODE = true: demo Sheet + a fixed demo week (for sales demos). false: real Sheet, last full Monday-Sunday week.
// DEMO_MODE = true: Sheet demo + una semana fija de demostración. false: Sheet real, la semana pasada completa.
const DEMO_MODE = true;
return [{ json: DEMO_MODE
  ? { sheet: 'demo', desde: '2026-10-20', hasta: '2026-10-26' }
  : { sheet: 'real', desde: '', hasta: '' } }];

// Monday WhatsApp for the owner: last week in 30 seconds. Only numbers from P36d; nothing written by AI.
// WhatsApp del lunes para la dueña: la semana pasada en 30 segundos. Solo números de P36d; nada lo escribe la IA.
const m = $input.first().json;
const P = m.periodo, B = m.anterior, n = m.negocio || {};
const es = String(n.idioma_duena || 'en').startsWith('es');
const loc = es ? 'es-MX' : 'en-US';
const usd = v => '$' + Math.round(v).toLocaleString(loc);
const d1 = DateTime.fromISO(P.desde).setLocale(es ? 'es' : 'en'), d2 = DateTime.fromISO(P.hasta).setLocale(es ? 'es' : 'en');
const sameMonth = d1.month === d2.month;
const rango = es
  ? (sameMonth ? `${d1.toFormat('d')} al ${d2.toFormat('d LLL')}` : `${d1.toFormat('d LLL')} al ${d2.toFormat('d LLL')}`)
  : (sameMonth ? `${d1.toFormat('LLL d')}-${d2.toFormat('d')}` : `${d1.toFormat('LLL d')} - ${d2.toFormat('LLL d')}`);
const delta = B.total_usd > 0 ? Math.round(100 * (P.total_usd - B.total_usd) / B.total_usd) : null;
const trend = delta === null ? '' : (delta >= 0 ? '↑ ' : '↓ ') + Math.abs(delta) + ' %';
const plural = (k, one, many) => k === 1 ? one : many;

const L = es ? [
  `📊 *${n.nombre || 'Lumière'} · semana del ${rango}*`,
  `• ${P.leads} ${plural(P.leads, 'lead nuevo', 'leads nuevos')}` + (P.respuesta_prom_seg !== null ? `, respondidos en ~${P.respuesta_prom_seg} s` : '') + (P.leads_fuera_horario ? ` (${P.leads_fuera_horario} fuera de horario)` : ''),
  `• ${P.citas_agendadas} ${plural(P.citas_agendadas, 'cita agendada', 'citas agendadas')} por Sofía, sin recepcionista`,
  P.no_shows_evitados ? `• ${P.no_shows_evitados} ${plural(P.no_shows_evitados, 'no-show evitado', 'no-shows evitados')} ≈ ${usd(P.valor_no_shows_usd)}` : '',
  [P.clientas_que_vuelven ? `${P.clientas_que_vuelven} ${plural(P.clientas_que_vuelven, 'clienta volvió', 'clientas volvieron')}` : '',
   P.resenas_pedidas ? `${P.resenas_pedidas} ${plural(P.resenas_pedidas, 'reseña pedida', 'reseñas pedidas')}` : ''].filter(Boolean).join(' · ').replace(/^(.+)$/, '• $1'),
  `⏱️ ~${Math.round(P.horas_ahorradas)} h de recepción ahorradas`,
  `💰 Valor estimado: *${usd(P.total_usd)}*` + (trend ? ` (${trend} vs. la semana anterior)` : ''),
  m.casos_abiertos ? `⚠️ ${m.casos_abiertos} ${plural(m.casos_abiertos, 'caso abierto espera', 'casos abiertos esperan')} a tu equipo` : ''
] : [
  `📊 *${n.nombre || 'Lumière'} · week of ${rango}*`,
  `• ${P.leads} new ${plural(P.leads, 'lead', 'leads')}` + (P.respuesta_prom_seg !== null ? `, answered in ~${P.respuesta_prom_seg}s` : '') + (P.leads_fuera_horario ? ` (${P.leads_fuera_horario} after hours)` : ''),
  `• ${P.citas_agendadas} ${plural(P.citas_agendadas, 'appointment', 'appointments')} booked by Sofía, no front desk needed`,
  P.no_shows_evitados ? `• ${P.no_shows_evitados} ${plural(P.no_shows_evitados, 'no-show', 'no-shows')} avoided ≈ ${usd(P.valor_no_shows_usd)}` : '',
  [P.clientas_que_vuelven ? `${P.clientas_que_vuelven} ${plural(P.clientas_que_vuelven, 'client', 'clients')} came back` : '',
   P.resenas_pedidas ? `${P.resenas_pedidas} ${plural(P.resenas_pedidas, 'review', 'reviews')} requested` : ''].filter(Boolean).join(' · ').replace(/^(.+)$/, '• $1'),
  `⏱️ ~${Math.round(P.horas_ahorradas)} front-desk hours saved`,
  `💰 Estimated value: *${usd(P.total_usd)}*` + (trend ? ` (${trend} vs. the week before)` : ''),
  m.casos_abiertos ? `⚠️ ${m.casos_abiertos} open ${plural(m.casos_abiertos, 'case is', 'cases are')} waiting for your team` : ''
];
const whatsapp = '+' + String(n.whatsapp_duena || '').replace(/\D/g, '');
if (whatsapp.length < 12) return [];
// Inputs of P31e - Lumière Send WhatsApp (no client: empty lead_id)
return [{ json: { lead_id: '', whatsapp, mensaje: L.filter(Boolean).join('\n'), rol: 'reporte_duena', origen: 'P36' } }];
